:root {


  --janso-font-display: 'Inter', 'Segoe UI Variable Display', 'Segoe UI', system-ui, -apple-system, sans-serif;
  --janso-font-body: 'Inter', 'Segoe UI Variable Text', 'Segoe UI', system-ui, -apple-system, sans-serif;

  --janso-font-mono: ui-monospace, 'Cascadia Mono', 'Segoe UI Mono', 'SF Mono', Menlo, monospace;


  --janso-text-overline: 0.6875rem; 
  --janso-text-xs: 0.75rem; 
  --janso-text-sm: 0.8125rem; 
  --janso-text-base: 0.875rem; 
  --janso-text-md: 0.9375rem; 
  --janso-text-lg: 1.125rem; 
  --janso-text-xl: 1.5rem; 
  --janso-text-2xl: 2rem; 


  --janso-figure-sm: 1.25rem; 
  --janso-figure-lg: 1.75rem; 


  --janso-space-1: 0.25rem;
  --janso-space-2: 0.5rem;
  --janso-space-3: 0.75rem;
  --janso-space-4: 1rem;
  --janso-space-5: 1.5rem;
  --janso-space-6: 2rem;
  --janso-space-7: 3rem;
  --janso-space-8: 4rem;


  --janso-radius-sm: 6px;
  --janso-radius-md: 10px;
  --janso-radius-pill: 999px;


  --janso-dur-fast: 100ms;
  --janso-dur: 160ms;
  --janso-ease: cubic-bezier(0.25, 0.8, 0.25, 1);


  --janso-rail-w: 248px;
  --janso-rail-w-collapsed: 64px;

  --janso-topbar-h: 3.5rem;
  --janso-page-gutter: 2rem;
  --janso-action-card-compact-min: 16rem;
  --janso-action-card-compact-height: 17rem;
  --janso-page-max: 1440px;
  --janso-control-h: 2.25rem;
  --janso-entry-subject-w: 18rem;
  --janso-entry-quantity-w: 6rem;
  --janso-entry-amount-w: 7rem;
  --janso-entry-kind-w: 7rem;
  --janso-filter-control-h: var(--janso-control-h);
  --janso-filter-controls-min: 18rem;
  --janso-filter-search-min: 10rem;
  --janso-filter-search-max: 26rem;
  --janso-report-viewport-height: 65vh;
  --janso-report-table-min: 56rem;
  --janso-report-detail-min: 28rem;



  --janso-z-sticky: 10;
  --janso-z-topbar: 20;
  --janso-z-rail: 30;
  --janso-z-scrim: 40;
  --janso-z-drawer: 50;
  --janso-z-popover: 60;
  --janso-z-tooltip: 70;

  --janso-z-toast: 80;
}




[data-theme='light'],
:root:not([data-theme]) {

  --janso-paper: #f7f7f9; 
  --janso-surface: #ffffff; 
  --janso-surface-2: #fafafb; 
  --janso-overlay: #ffffff; 
  --janso-panel: #f3f3f8; 
  --janso-panel-2: #ebecf4; 
  --janso-hover: #f3f4f7;
  --janso-active: #ebedf2;
  --janso-selected: #f1f1fd;
  --janso-disabled-surface: #f2f3f5;
  --janso-disabled-ink: #696e7a;
  --janso-scrim: rgba(15, 17, 26, 0.36);


  --janso-ink: #15171c; 
  --janso-ink-soft: #585d68; 
  --janso-ink-faint: #676c78; 
  --janso-ink-invert: #ffffff; 


  --janso-brand: #4a4fd4; 
  --janso-brand-strong: #3d41bd; 
  --janso-brand-bright: #6e72ef; 
  --janso-brand-ink: #2e3190; 
  --janso-wordmark-books: #14693f; 
  --janso-brand-tint: #f1f1fd;
  --janso-brand-line: #d8d9f8;
  --janso-brand-glow: rgba(74, 79, 212, 0.1); 


  --janso-line: #e8e9ed; 
  --janso-line-strong: #d5d7dd; 
  --janso-control-line: #878c98; 
  --janso-overlay-line: #e1e3e8; 


  --janso-success-ink: #167447;
  --janso-success-tint: #edf8f2;
  --janso-success-line: #c6e7d4;
  --janso-warn-ink: #8c5806;
  --janso-warn-tint: #fdf6e8;
  --janso-warn-line: #f0dba9;
  --janso-danger-ink: #bf3529; 
  --janso-danger-tint: #fdf1f0;
  --janso-danger-line: #f4cfca;
  --janso-info-ink: #22629f;
  --janso-info-tint: #eef5fc;
  --janso-info-line: #cadcf1;
  --janso-neutral-ink: #585d68;
  --janso-neutral-tint: #f2f3f5;
  --janso-neutral-line: #e2e4e8;


  --janso-grad-mark: linear-gradient(150deg, #6366f1 0%, #4338ca 100%);
  --janso-grad-action: linear-gradient(180deg, #5257dc 0%, #4549cc 100%);
  --janso-grad-action-press: linear-gradient(180deg, #4246c4 0%, #383caf 100%);
  --janso-grad-panel: linear-gradient(165deg, #f7f7fc 0%, #ecedf6 100%);


  --janso-focus: #4a4fd4;
  --janso-focus-ring: 0 0 0 1px var(--janso-surface), 0 0 0 3px var(--janso-focus), 0 0 0 6px rgba(74, 79, 212, 0.16);
  --janso-focus-ring-danger: 0 0 0 1px var(--janso-surface), 0 0 0 3px var(--janso-danger-ink), 0 0 0 6px rgba(191, 53, 41, 0.16);


  --janso-shadow-action: 0 1px 2px rgba(25, 27, 80, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.14);
  --janso-shadow-card: 0 1px 2px rgba(16, 18, 27, 0.04), 0 1px 3px rgba(16, 18, 27, 0.03);
  --janso-shadow-popover: 0 16px 36px -12px rgba(16, 18, 27, 0.2), 0 4px 10px -4px rgba(16, 18, 27, 0.08);
  --janso-shadow-inset-mark: inset 0 1px 0 rgba(255, 255, 255, 0.22), 0 1px 2px rgba(25, 27, 80, 0.3);


  --janso-meter-track: #ebedf1;
  --janso-meter-fill: #4a4fd4;
  --janso-spinner-track: rgba(255, 255, 255, 0.45);
  --janso-spinner-head: #ffffff;


  --janso-chart-1: #4a4fd4; 
  --janso-chart-2: #c28412; 
  --janso-chart-3: #009394; 
  --janso-chart-4: #aa3f4e; 
  --janso-chart-5: #419bd4; 
  --janso-chart-6: #5b6c00; 
  --janso-chart-7: #97549b; 
  --janso-chart-8: #88470d; 
  --janso-chart-grid: #eef0f3;
  --janso-chart-axis: #6f7891; 


  --janso-canvas-backdrop: #e9eaee;
  --janso-canvas-backdrop-2: #dfe1e6;
  --janso-canvas-page-edge: #c9ccd3;
  --janso-canvas-page-shadow: rgba(16, 18, 26, 0.14);
  --janso-canvas-ruler-bg: #f4f5f8;
  --janso-canvas-ruler-ink: #6b7180;
  --janso-canvas-ruler-tick: #b4b9c4;
  --janso-canvas-ruler-marker: #4a4fd4;
  --janso-editor-chrome: #f7f7f9;
  --janso-editor-chrome-2: #eef0f4;
  --janso-editor-chrome-line: #dcdee4;
  --janso-editor-chrome-ink: #15171c;
  --janso-editor-chrome-ink-soft: #5c6271;

  --janso-canvas-page: #ffffff;
  --janso-canvas-page-ink: #101114;
  --janso-canvas-page-ink-soft: #4a4f59;
  --janso-canvas-page-line: #d8dade;
  --janso-canvas-page-line-strong: #9aa0aa;
  --janso-canvas-page-tint: #f1f2f5;
  --janso-canvas-grid-dot: #c6cad2;
  --janso-canvas-margin-line: #7f88d0; 
  --janso-canvas-bleed: rgba(170, 63, 78, 0.08);
  --janso-canvas-zone-line: #7f84ee; 
  --janso-canvas-zone-tint: rgba(74, 79, 212, 0.05);
  --janso-canvas-zone-label-bg: #4a4fd4;
  --janso-canvas-zone-label-ink: #ffffff;
  --janso-canvas-ring: #4a4fd4;
  --janso-canvas-ring-muted: #9a9df0;
  --janso-canvas-marquee-tint: rgba(74, 79, 212, 0.10);
  --janso-canvas-handle-fill: #ffffff;
  --janso-canvas-handle-line: #4a4fd4;
  --janso-canvas-guide: #c28412;
  --janso-canvas-badge-bg: rgba(16, 18, 26, 0.82);
  --janso-canvas-badge-ink: #ffffff;
  --janso-canvas-copy-mark: rgba(16, 18, 26, 0.07);
}


:root {
  --report-font: 'Report Sans', 'Report Devanagari', sans-serif;
  --report-body-size: 0.8125rem;
  --report-pdf-body-size: 8;
  --report-pdf-heading-size: 20;
  --report-pdf-leading: 12;
  --report-pdf-margin: 36;
  --report-pdf-padding: 5;
  --report-xlsx-body-size: 11;
}
.report-document { margin: 0; color: var(--janso-ink); background: var(--janso-surface); font-family: var(--report-font); font-size: var(--report-body-size); }
.report-shell { padding: var(--janso-space-6); }
.report-header { border-top: var(--janso-space-1) solid var(--janso-brand); padding-top: var(--janso-space-5); margin-bottom: var(--janso-space-5); }
.report-eyebrow { color: var(--janso-ink-soft); font-size: var(--janso-text-overline); letter-spacing: 0.08em; text-transform: uppercase; }
.report-title { margin: var(--janso-space-2) 0; font-size: var(--janso-text-2xl); font-weight: 700; line-height: 1.2; }
.report-company { font-size: var(--janso-text-lg); margin: var(--janso-space-2) 0; }
.report-meta { display: flex; flex-wrap: wrap; gap: var(--janso-space-5); color: var(--janso-ink-soft); border-block: 1px solid var(--janso-line); padding-block: var(--janso-space-3); }
.report-meta dt { font-size: var(--janso-text-overline); text-transform: uppercase; }
.report-meta dd { margin: var(--janso-space-1) 0 0; color: var(--janso-ink); }
.report-table-wrap { overflow-x: auto; }
.report-table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.report-table th { text-align: left; color: var(--janso-brand-ink); background: var(--janso-brand-tint); font-weight: 700; border-bottom: 1px solid var(--janso-line-strong); }
.report-table th, .report-table td { padding: var(--janso-space-3); vertical-align: top; overflow-wrap: anywhere; white-space: pre-wrap; }
.report-table td { border-bottom: 1px solid var(--janso-line); }
.report-table .report-number { text-align: right; white-space: nowrap; }
.report-table .report-total td { font-weight: 700; border-top: 1px solid var(--janso-ink-soft); background: var(--janso-surface-2); }
.report-table .report-control td { font-weight: 700; background: var(--janso-panel); }
.report-statement .report-table { max-width: 72rem; }
.report-summary .report-table { max-width: 64rem; }
.report-reconciliation .report-table td:first-child { font-weight: 700; }
.report-footer { border-top: 1px solid var(--janso-line-strong); margin-top: var(--janso-space-5); padding-top: var(--janso-space-3); color: var(--janso-ink-soft); font-size: var(--janso-text-xs); overflow-wrap: anywhere; }
.report-empty { padding: var(--janso-space-6); text-align: center; color: var(--janso-ink-soft); }
@media print {
  @page { size: A4 landscape; margin: 12mm; }
  .report-shell { padding: 0; }
  .report-table-wrap { overflow: visible; }
  .report-table thead { display: table-header-group; }
  .report-table tr { break-inside: avoid; }
  .report-title { break-after: avoid; }
}
